create policy marketplace_ads_seller_insert_own on public.marketplace_ads for insert to authenticated with check (owner_id = (select auth.uid()) and status = 'pending' and quoted_price is null and starts_at is null and ends_at is null and exists (select 1 from public.shops s where s.id = shop_id and s.owner_id = (select auth.uid()) and s.status = 'approved') and exists (select 1 from public.products p where p.id = product_id and p.shop_id = shop_id and p.status = 'active') and (select current_user_has_role('seller')))
